import * as THREE from 'three';
import { GLSL_NOISE, mulberry32 } from '../core/noise.js';
import { canvasTexture } from '../core/utils.js';
import { COATS, proportions, BREEDS } from './breeds.js';
import { ARCHETYPES, ARCHETYPE_KEYS, archetypeFor, skeleton, boneWorldMatrices, invertRigid, apply, HEAD_REST, EAR_REST } from './anatomy.js';

// ---------------------------------------------------------------------------
// Asset loading (meshes generated by tools/build-horses.mjs)
// ---------------------------------------------------------------------------
const ASSETS = {};
let LEVELS = ['', '-lo'];

function parseHorse(buf, P) {
  const u32 = new Uint32Array(buf, 0, 5);
  const [, n, ni, metaLen, big] = u32;
  let o = 20;
  const meta = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, o, metaLen)));
  o += metaLen;
  const take = (Ctor, count) => { const bytes = count * Ctor.BYTES_PER_ELEMENT; const a = new Ctor(buf.slice(o, o + bytes)); o += bytes; return a; };
  const posQ = take(Int16Array, n * 3);
  const nor = take(Int8Array, n * 3);
  const ao = take(Uint8Array, n);
  const part = take(Uint8Array, n);
  const si = take(Uint8Array, n * 4);
  const sw = take(Uint8Array, n * 4);
  const ind = big ? take(Uint32Array, ni) : take(Uint16Array, ni);
  const pos = new Float32Array(n * 3);
  for (let i = 0; i < n * 3; i++) pos[i] = posQ[i] / 10000;
  // head-local coordinates for face markings
  const { bones } = skeleton(P);
  const world = boneWorldMatrices(bones);
  const headIdx = bones.findIndex((b) => b.name === 'head');
  const inv = invertRigid(world[headIdx]);
  const local = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const l = apply(inv, [pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2]]);
    local[i * 3] = l[0]; local[i * 3 + 1] = l[1]; local[i * 3 + 2] = l[2];
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3, true));
  g.setAttribute('aAO', new THREE.BufferAttribute(ao, 1, true));
  g.setAttribute('aPart', new THREE.BufferAttribute(new Float32Array(part), 1));
  g.setAttribute('aLocal', new THREE.BufferAttribute(local, 3));
  g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(new Uint16Array(si), 4));
  g.setAttribute('skinWeight', new THREE.BufferAttribute(sw, 4, true));
  g.setIndex(new THREE.BufferAttribute(ind, 1));
  g.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 1.2, 0.2), 2.4);
  return { geometry: g, meta };
}

// levels: e.g. ['', '-lo'] (desktop) or ['-mid', '-lo'] (mobile)
export async function loadHorseAssets(levels = LEVELS, onProgress) {
  LEVELS = levels;
  let done = 0;
  const todo = ARCHETYPE_KEYS.flatMap((k) => levels.map((lv) => [k, lv])).filter(([k, lv]) => !ASSETS[k + lv]);
  const total = todo.length || 1;
  if (!todo.length && onProgress) onProgress(1);
  await Promise.all(todo.map(async ([k, lv]) => {
    const res = await fetch(`assets/horses/${k}${lv}.bin`);
    if (!res.ok) throw new Error(`Pferdemodell ${k}${lv} fehlt`);
    const buf = await res.arrayBuffer();
    ASSETS[k + lv] = parseHorse(buf, ARCHETYPES[k]);
    done++;
    if (onProgress) onProgress(done / total);
  }));
}

// ---------------------------------------------------------------------------
// Hair strand texture (shared)
// ---------------------------------------------------------------------------
let STRANDS = null;
function strandTexture() {
  if (STRANDS) return STRANDS;
  const rnd = mulberry32(31);
  STRANDS = canvasTexture(128, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    for (let i = 0; i < 160; i++) {
      const x = rnd() * w;
      const len = h * (0.55 + rnd() * 0.45);
      const v = 150 + rnd() * 105;
      g.strokeStyle = `rgba(${v},${v},${v},${0.55 + rnd() * 0.45})`;
      g.lineWidth = 1 + rnd() * 2.2;
      g.beginPath();
      g.moveTo(x, 0);
      const sway = (rnd() - 0.5) * 18;
      g.bezierCurveTo(x + sway, len * 0.35, x - sway, len * 0.7, x + sway * 0.5, len);
      g.stroke();
    }
    const grd = g.createLinearGradient(0, 0, 0, h * 0.25);
    grd.addColorStop(0, 'rgba(200,200,200,0.9)'); grd.addColorStop(1, 'rgba(200,200,200,0)');
    g.fillStyle = grd; g.fillRect(0, 0, w, h * 0.25);
  });
  STRANDS.wrapS = THREE.RepeatWrapping;
  return STRANDS;
}

// ---------------------------------------------------------------------------
// Coat shader
// ---------------------------------------------------------------------------
const COAT_GLSL = /* glsl */`
${GLSL_NOISE}
float vor(vec3 x){
  vec3 p = floor(x); vec3 f = fract(x); float res = 8.0;
  for(int k=-1;k<=1;k++) for(int j=-1;j<=1;j++) for(int i=-1;i<=1;i++){
    vec3 b = vec3(float(i),float(j),float(k));
    vec3 r = b - f + vec3(hash13(p+b), hash13(p+b+17.17), hash13(p+b+31.31));
    res = min(res, dot(r,r));
  }
  return sqrt(res);
}
vec3 coatColor(vec3 p, vec3 lp, float part){
  float n = fbm3(p*3.0 + uSeed);
  vec3 col = uBase * (0.9 + 0.2*n);
  float legZone = 1.0 - smoothstep(0.42, 0.64, p.y + (n-0.5)*0.1);
  col = mix(col, uPoint, legZone * (uPoints > 0.5 ? 1.0 : 0.7));
  if (uDorsal > 0.5) {
    float d = smoothstep(0.05, 0.015, abs(p.x)) * smoothstep(uTopY-0.12, uTopY+0.0, p.y) * step(p.z, uBodyFront) * step(-uBodyFront, p.z);
    col = mix(col, uPoint, d*0.85);
  }
  if (uPattern == 1) {
    float v = vor(p*7.5 + uSeed);
    col = mix(col, uPatternColor, smoothstep(0.35, 0.65, v) * smoothstep(0.7, 1.15, p.y) * 0.55);
    col = mix(col, uPoint, (1.0 - smoothstep(0.2, 0.75, p.y))*0.5);
  } else if (uPattern == 2) {
    float t = fbm3(vec3(p.x*1.4, p.y*2.3, p.z*2.6) + uSeed*1.7);
    col = mix(col, uPatternColor, smoothstep(0.5, 0.52, t + (1.25 - p.y)*0.14));
  } else if (uPattern == 3) {
    float v = vor(p*9.0 + uSeed);
    float rad = 0.32 + 0.12*vnoise(p*20.0);
    col = mix(col, uPatternColor*(0.8+0.4*n), smoothstep(rad, rad-0.08, v)*0.92);
  } else if (uPattern == 4) {
    float blanket = smoothstep(0.08, -0.12, p.z + (n-0.5)*0.35) * smoothstep(0.92, 1.18, p.y + (n-0.5)*0.1);
    col = mix(col, uPatternColor, blanket);
    float v = vor(p*11.0 + uSeed);
    col = mix(col, uBase*0.7, smoothstep(0.32, 0.2, v) * blanket);
  }
  if (part > 2.5 && part < 6.5) {
    int li = int(part - 3.0 + 0.5);
    float sh = li==0 ? uSocks.x : li==1 ? uSocks.y : li==2 ? uSocks.z : uSocks.w;
    if (sh > 0.0) {
      float edge = sh + (vnoise(p*30.0)-0.5)*0.05;
      col = mix(col, vec3(0.94,0.93,0.9), smoothstep(edge+0.01, edge-0.01, p.y));
    }
  }
  if (part > 6.5) {
    int li = int(part - 7.0 + 0.5);
    float sh = li==0 ? uSocks.x : li==1 ? uSocks.y : li==2 ? uSocks.z : uSocks.w;
    col = sh > 0.0 ? vec3(0.42,0.36,0.27) : vec3(0.035,0.03,0.028);
    col *= 0.85 + 0.3*vnoise(vec3(p.x*40.0, p.y*400.0, p.z*40.0));
  }
  if (part > 1.5 && part < 2.5) {
    float t = clamp(lp.y / uHeadLen, 0.0, 1.0);
    if (uBlaze > 0.5) {
      float w = uBlaze > 1.5 ? mix(0.05, 0.06, t) : mix(0.035, 0.018, t);
      float star = uBlaze > 1.5 ? 1.0 : smoothstep(0.75, 0.6, t);
      float b = smoothstep(w, w-0.01, abs(lp.x + (vnoise(lp*25.0)-0.5)*0.01)) * step(lp.z, -0.02) * smoothstep(0.08, 0.14, t) * star;
      col = mix(col, vec3(0.95,0.94,0.92), b);
    }
    // bare, darker skin on the muzzle and around the eyes
    float muzzle = smoothstep(0.7, 0.88, t + (vnoise(lp*30.0)-0.5)*0.04);
    col = mix(col, uBlaze > 1.5 ? vec3(0.36,0.2,0.18) : vec3(0.045,0.035,0.032), muzzle*0.85);
    float eyeRing = smoothstep(0.075, 0.03, length(vec2(lp.y - uHeadLen*0.3, lp.z + 0.035))) * step(0.06, abs(lp.x));
    col = mix(col, col*0.45, eyeRing);
  }
  float dm = smoothstep(0.5, 0.72, fbm3(p*6.0 + 3.0)) * (1.0 - smoothstep(0.25, 1.4, p.y));
  dm += smoothstep(0.55, 0.7, fbm3(p*4.0 + 9.0)) * 0.6;
  col = mix(col, vec3(0.1, 0.065, 0.035), clamp(dm,0.0,1.0) * uDirt);
  return col;
}
`;

function coatMaterial(coatKey, horse, breed, dims) {
  const c = COATS[coatKey] || COATS.brauner;
  const sheen = (c.sheen || breed.sheen) ? 1 : 0;
  const base = new THREE.Color().setRGB(...c.base, THREE.SRGBColorSpace);
  const uniforms = {
    uBase: { value: base },
    uPoint: { value: new THREE.Color().setRGB(...c.point, THREE.SRGBColorSpace) },
    uPatternColor: { value: new THREE.Color().setRGB(...(c.patternColor || c.base), THREE.SRGBColorSpace) },
    uPattern: { value: c.pattern },
    uPoints: { value: c.points ? 1 : 0 },
    uDorsal: { value: c.dorsal ? 1 : 0 },
    uSeed: { value: (parseInt(horse.id, 36) % 1000) * 0.137 },
    uSocks: { value: new THREE.Vector4(...(horse.markings?.socks || [0, 0, 0, 0])) },
    uBlaze: { value: horse.markings?.blaze || 0 },
    uDirt: { value: 0 },
    uTopY: { value: dims.topY },
    uBodyFront: { value: dims.zLen * 0.8 },
    uHeadLen: { value: dims.headLen },
    uSheen: { value: sheen },
    uWet: { value: 0 },
  };
  const m = new THREE.MeshPhysicalMaterial({
    color: 0xffffff, roughness: 0.55, metalness: 0,
    sheen: 0.9, sheenRoughness: 0.4, sheenColor: base.clone().lerp(new THREE.Color(1, 0.95, 0.85), 0.45),
    clearcoat: sheen ? 0.5 : 0.08, clearcoatRoughness: 0.45,
  });
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, uniforms);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec3 aLocal; attribute float aPart; attribute float aAO; varying vec3 vRest; varying vec3 vLocal; varying float vPart; varying float vAO;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvRest = position; vLocal = aLocal; vPart = aPart; vAO = aAO;');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
        uniform vec3 uBase; uniform vec3 uPoint; uniform vec3 uPatternColor; uniform int uPattern; uniform float uPoints; uniform float uDorsal;
        uniform float uSeed; uniform vec4 uSocks; uniform float uBlaze; uniform float uDirt; uniform float uTopY; uniform float uBodyFront;
        uniform float uHeadLen; uniform float uSheen; uniform float uWet;
        varying vec3 vRest; varying vec3 vLocal; varying float vPart; varying float vAO;
        ${COAT_GLSL}`)
      .replace('#include <color_fragment>', `#include <color_fragment>
        float aoF = mix(0.25, 1.0, vAO);
        diffuseColor.rgb = coatColor(vRest, vLocal, vPart) * (1.0 - uWet*0.25) * aoF;`)
      .replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
        float hairN = vnoise(vec3(vRest.x*60.0, vRest.y*12.0, vRest.z*60.0));
        roughnessFactor = mix(mix(0.6, 0.36, uSheen), 0.3, uWet) + (hairN-0.5)*0.12;
        if (vPart > 6.5) roughnessFactor = 0.35;`)
      .replace('#include <lights_physical_fragment>', `#include <lights_physical_fragment>
        // velvet sheen follows the coat colour so dark points and the muzzle stay dark
        material.sheenColor *= clamp(diffuseColor.rgb * 2.0, 0.0, 1.0);`)
      .replace('#include <metalnessmap_fragment>', '#include <metalnessmap_fragment>\n metalnessFactor = uSheen * 0.35;')
      .replace('#include <aomap_fragment>', `#include <aomap_fragment>
        reflectedLight.indirectDiffuse *= aoF; reflectedLight.indirectSpecular *= aoF;`);
  };
  m.userData.uniforms = uniforms;
  m.customProgramCacheKey = () => 'coat3';
  return m;
}

// ---------------------------------------------------------------------------
// Hair geometry helpers
// ---------------------------------------------------------------------------
// A curved card hanging along local -y (width along z), with a slight outward curl.
function lockGeo(len, w, curl = 0.04) {
  const g = new THREE.PlaneGeometry(w, len, 1, 6);
  const p = g.attributes.position;
  for (let k = 0; k < p.count; k++) {
    const yy = p.getY(k);
    const t = 0.5 - yy / len;
    p.setX(k, p.getX(k) * (1 - 0.5 * t));
    p.setZ(k, Math.sin(t * Math.PI) * 0.02 + t * t * curl);
    p.setY(k, yy - len / 2);
  }
  g.rotateY(Math.PI / 2);
  g.computeVertexNormals();
  return g;
}

function tailGeometry(boneWorld, tailIdx, volume, braided, rnd) {
  const pts = tailIdx.map((i) => new THREE.Vector3(boneWorld[i][12], boneWorld[i][13], boneWorld[i][14]));
  const last = pts[pts.length - 1], prev = pts[pts.length - 2];
  pts.push(last.clone().add(last.clone().sub(prev)));
  const curve = new THREE.CatmullRomCurve3(pts);
  const R = 22;
  const pos = [], uv = [], si = [], sw = [], idx = [];
  const cards = braided ? 3 : 9;
  const seg = tailIdx.length;
  for (let c = 0; c < cards; c++) {
    const phi = (c / cards) * Math.PI + rnd() * 0.3;
    const lateral = braided ? 0 : (rnd() - 0.5) * 0.04;
    const base = pos.length / 3;
    for (let r = 0; r <= R; r++) {
      const s = 0.04 + (r / R) * 0.96;
      const p = curve.getPointAt(s);
      const t = curve.getTangentAt(s);
      const side = new THREE.Vector3(1, 0, 0);
      const n2 = new THREE.Vector3().crossVectors(t, side).normalize();
      const dir = side.clone().multiplyScalar(Math.cos(phi)).addScaledVector(n2, Math.sin(phi));
      let w = braided ? 0.03 + 0.01 * Math.sin(s * 30) : (0.035 + 0.12 * Math.sin(Math.min(1, s * 1.15) * Math.PI * 0.8)) * volume;
      if (!braided && s > 0.85) w *= 1 - (s - 0.85) * 2.5;
      const off = new THREE.Vector3().crossVectors(t, dir).multiplyScalar(lateral);
      for (const u of [-1, 1]) {
        const q = p.clone().addScaledVector(dir, u * w).add(off);
        pos.push(q.x, q.y, q.z);
        uv.push(((u + 1) / 2) * 0.5 + c * 0.17, s);
        const f = s * seg;
        const b0 = Math.min(seg - 1, Math.floor(f)), b1 = Math.min(seg - 1, b0 + 1);
        const fr = Math.min(1, f - b0);
        si.push(tailIdx[b0], tailIdx[b1], 0, 0);
        sw.push(1 - fr, fr, 0, 0);
      }
      if (r < R) { const a = base + r * 2; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(si, 4));
  g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(sw, 4));
  g.setIndex(idx);
  g.computeVertexNormals();
  g.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 1.2, -0.8), 2);
  return g;
}

// ---------------------------------------------------------------------------
// Builder
// ---------------------------------------------------------------------------
export function buildHorseModel(horse) {
  const P = proportions(horse);
  const breed = BREEDS[horse.breed];
  const coat = COATS[horse.coat] || COATS.brauner;
  const arch = archetypeFor(P);
  const AP = ARCHETYPES[arch];
  const { bones: boneDefs, dims: d } = skeleton(AP);
  const hi = ASSETS[arch + LEVELS[0]], lo = ASSETS[arch + LEVELS[1]];
  const meta = hi.meta;
  const rnd = mulberry32(parseInt(horse.id, 36) % 100000);

  const backAt = (z) => {
    const [z0, z1] = meta.backZ;
    const f = Math.min(1, Math.max(0, (z - z0) / (z1 - z0))) * (meta.backTop.length - 1);
    const i = Math.min(meta.backTop.length - 2, Math.floor(f));
    return meta.backTop[i] + (meta.backTop[i + 1] - meta.backTop[i]) * (f - i);
  };
  const headSection = (t) => {
    const hs = meta.headSection;
    const f = Math.min(1, Math.max(0, t)) * (hs.length - 1);
    const i = Math.min(hs.length - 2, Math.floor(f));
    const a = hs[i], b = hs[i + 1], k = f - i;
    return { rx: a.rx + (b.rx - a.rx) * k, rz: a.rz + (b.rz - a.rz) * k, cz: a.cz + (b.cz - a.cz) * k, y: a.y + (b.y - a.y) * k };
  };
  const dims = {
    hipF: d.hipF, hipH: d.hipH, cy: d.cy, zLen: d.zLen, neckLen: d.neckLen, headLen: d.headLen,
    topY: backAt(d.zLen * 0.5), size: P.size, neckTilt: d.neckTilt, saddleY: backAt(d.zLen * 0.12),
    bulk: d.bulk, legThick: d.th, headSection, headRest: HEAD_REST, earRest: EAR_REST,
  };

  const coatMat = coatMaterial(horse.coat, horse, breed, dims);
  const hairColor = new THREE.Color().setRGB(...coat.mane, THREE.SRGBColorSpace);
  const hairMat = new THREE.MeshStandardMaterial({ color: hairColor, map: strandTexture(), alphaTest: 0.32, side: THREE.DoubleSide, roughness: 0.5 });
  const eyeMat = new THREE.MeshPhysicalMaterial({ color: 0x120804, roughness: 0.05, clearcoat: 1, clearcoatRoughness: 0.02 });
  const lidMat = new THREE.MeshStandardMaterial({ color: 0x24170f, roughness: 0.7 });

  // --- skeleton
  const root = new THREE.Group();
  const bones = boneDefs.map((b) => {
    const bone = new THREE.Bone();
    bone.name = b.name;
    bone.position.set(...b.pos);
    bone.rotation.set(...b.rot);
    return bone;
  });
  boneDefs.forEach((b, i) => { if (b.parent >= 0) bones[b.parent].add(bones[i]); else root.add(bones[i]); });
  const B = Object.fromEntries(bones.map((b) => [b.name, b]));
  root.updateMatrixWorld(true);
  const skel = new THREE.Skeleton(bones);

  const makeSkinned = (geo, mat) => {
    const m = new THREE.SkinnedMesh(geo, mat);
    m.bind(skel, new THREE.Matrix4());
    m.castShadow = true; m.receiveShadow = true;
    m.boundingSphere = geo.boundingSphere.clone();
    root.add(m);
    return m;
  };
  const meshHi = makeSkinned(hi.geometry, coatMat);
  const meshLo = makeSkinned(lo.geometry, coatMat);
  meshLo.visible = false;

  // --- eyes
  for (const s of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.03, 20, 14), eyeMat);
    eye.position.set(s * (meta.eye[0] + 0.002), meta.eye[1], meta.eye[2]);
    eye.scale.set(0.55, 1, 1.3);
    B.head.add(eye);
    // dark eyelid rim
    const lid = new THREE.Mesh(new THREE.TorusGeometry(0.032, 0.007, 6, 20), lidMat);
    lid.position.copy(eye.position).setX(s * (meta.eye[0] - 0.004));
    lid.rotation.y = Math.PI / 2;
    lid.scale.set(1.25, 1, 1);
    lid.rotation.z = 0.2;
    B.head.add(lid);
  }

  // --- legs
  const legs = ['FL', 'FR', 'HL', 'HR'].map((n, i) => {
    const front = i < 2;
    const hoofMarker = new THREE.Object3D();
    hoofMarker.position.set(0, -0.08, 0.012);
    B['hoof' + n].add(hoofMarker);
    return {
      front, side: i % 2 ? -1 : 1, segs: front ? d.fSeg : d.hSeg,
      rest: [B['hip' + n].rotation.x, B['knee' + n].rotation.x, B['fet' + n].rotation.x],
      hip: B['hip' + n], knee: B['knee' + n], fet: B['fet' + n], hoofPivot: B['hoof' + n], hoof: hoofMarker,
    };
  });
  if (P.feather > 0.05) {
    const socks = horse.markings?.socks || [];
    legs.forEach((leg, i) => {
      const mat = socks[i] > 0 ? new THREE.MeshStandardMaterial({ color: 0xf2eee6, map: strandTexture(), alphaTest: 0.32, side: THREE.DoubleSide, roughness: 0.6 }) : hairMat;
      const len = 0.13 + 0.1 * P.feather;
      const geo = lockGeo(len, 0.09, 0.015);
      for (let k = 0; k < 14; k++) {
        const card = new THREE.Mesh(geo, mat);
        const a = (k / 14) * Math.PI * 2;
        card.position.set(Math.cos(a) * 0.04 * d.th, 0.03, Math.sin(a) * 0.04 * d.th - 0.005);
        card.rotation.set(0, -a, 0.1 + (k % 2) * 0.05);
        card.castShadow = true;
        leg.fet.add(card);
      }
    });
  }

  // --- tail (skinned hair cards following the tail bones)
  const world = boneWorldMatrices(boneDefs);
  const tailIdx = boneDefs.map((b, i) => (b.name.startsWith('tail') ? i : -1)).filter((i) => i >= 0);
  const tailFull = new THREE.SkinnedMesh(tailGeometry(world, tailIdx, Math.min(1.4, P.tailLen), false, rnd), hairMat);
  const tailBraid = new THREE.SkinnedMesh(tailGeometry(world, tailIdx, 1, true, rnd), hairMat);
  for (const t of [tailFull, tailBraid]) {
    t.bind(skel, new THREE.Matrix4());
    t.castShadow = true;
    t.boundingSphere = t.geometry.boundingSphere.clone();
    root.add(t);
  }
  tailBraid.visible = false;
  const tail = tailIdx.map((i, k) => ({ g: bones[i], rest: k === 0 ? (breed.tailHigh ? 0.35 : 0.7) : -0.12 }));

  // --- mane (hair cards along the crest)
  const neck = B.neck, head = B.head;
  const N = d.neckLen;
  const mane = [];
  const maneGroup = new THREE.Group();
  neck.add(maneGroup);
  const fjord = breed.maneStyle === 'fjord';
  const lockCount = 20;
  const crestZ = (y) => {
    const c = meta.crest, [y0, y1] = meta.crestY;
    const f = Math.min(1, Math.max(0, (y - y0) / (y1 - y0))) * (c.length - 1);
    const i = Math.min(c.length - 2, Math.floor(f));
    return c[i] + (c[i + 1] - c[i]) * (f - i) + 0.012;
  };
  for (let i = 0; i < lockCount; i++) {
    const t = i / (lockCount - 1);
    const y = -0.04 + t * (N + 0.02);
    const lock = new THREE.Group();
    lock.position.set(0, y, crestZ(y));
    maneGroup.add(lock);
    let len = (0.2 + 0.24 * Math.sin(0.4 + t * 2.4)) * P.maneLen * (0.85 + rnd() * 0.3);
    if (fjord) len = 0.1;
    const layers = fjord ? 1 : 3;
    for (let l = 0; l < layers; l++) {
      const m = new THREE.Mesh(lockGeo(len * (1 - l * 0.12), 0.16 + rnd() * 0.05), hairMat);
      m.position.set(-l * 0.012, 0, (rnd() - 0.5) * 0.02);
      m.rotation.y = (rnd() - 0.5) * 0.4;
      m.rotation.z = -l * 0.1;
      m.castShadow = l === 0;
      lock.add(m);
    }
    if (fjord) {
      const dark = new THREE.Mesh(lockGeo(0.105, 0.05), new THREE.MeshStandardMaterial({ color: 0x14100c, map: strandTexture(), alphaTest: 0.3, side: THREE.DoubleSide }));
      dark.position.z = -0.004;
      lock.add(dark);
      lock.rotation.x = Math.PI - d.neckTilt;
    }
    mane.push({ g: lock, t, len, rest: fjord ? lock.rotation.x : -d.neckTilt + 0.15 });
  }
  const forelock = new THREE.Group();
  const hs0 = headSection(0.05);
  forelock.position.set(0, 0.0, hs0.cz - hs0.rz - 0.005);
  head.add(forelock);
  for (let l = 0; l < 2; l++) {
    const fl = new THREE.Mesh(lockGeo(0.18 * Math.max(0.6, P.maneLen), 0.12 - l * 0.03), hairMat);
    fl.rotation.y = l * 0.4;
    forelock.add(fl);
  }
  forelock.rotation.x = Math.PI + 0.25;

  // braids
  const braids = new THREE.Group();
  neck.add(braids);
  const braidGeo = new THREE.SphereGeometry(0.035, 10, 8);
  const braidMat = new THREE.MeshStandardMaterial({ color: hairColor, roughness: 0.5 });
  for (let i = 0; i < 9; i++) {
    const y = ((i + 0.5) / 9) * N;
    const b = new THREE.Mesh(braidGeo, braidMat);
    b.position.set(0, y, crestZ(y) - 0.03); b.scale.set(1, 1.3, 1.1);
    braids.add(b);
  }
  braids.visible = false;
  const bowGroup = new THREE.Group();
  neck.add(bowGroup);
  bowGroup.visible = false;

  // mount points
  const saddleMount = new THREE.Object3D();
  saddleMount.position.set(0, dims.saddleY, d.zLen * 0.12);
  B.body.add(saddleMount);
  const chestMount = new THREE.Object3D();
  chestMount.position.set(0, d.cy + 0.05, d.zLen * 0.93);
  B.body.add(chestMount);

  return {
    root, body: B.body, neck, head, ears: [B.earR, B.earL], legs, tail, mane, maneGroup, forelock, braids, bowGroup,
    saddleMount, chestMount, coatMat, hairMat, tailMeshes: [], meshHi, meshLo, tailFull, tailBraid, skeleton: skel,
    dims, P, arch,
    lod: 0,
    setLOD(level) {
      if (level === this.lod) return;
      this.lod = level;
      meshHi.visible = level === 0;
      meshLo.visible = level === 1;
      maneGroup.children.forEach((l) => l.children.forEach((m, k) => { m.visible = level === 0 || k === 0; }));
    },
    setTailBraid(v) { tailFull.visible = !v; tailBraid.visible = v; },
  };
}

export function disposeHorseModel(rig) {
  rig.root.traverse((o) => {
    if (o.isMesh && o !== rig.meshHi && o !== rig.meshLo) o.geometry.dispose();
  });
  rig.coatMat.dispose();
  rig.hairMat.dispose();
  rig.skeleton.dispose();
}
